WITH UserReputation AS (SELECT Id, Reputation, ROW_NUMBER() OVER (ORDER BY Reputation DESC NULLS FIRST) AS Rank FROM Users), PostStats AS (SELECT P.Id AS PostId, P.OwnerUserId, COUNT(CASE WHEN NOT (C.Id IS NULL) THEN 1 END) AS CommentCount, COUNT(DISTINCT PV.Id) AS VoteCount, AVG(COALESCE(P.Score, 0)) AS AverageScore FROM Posts AS P LEFT JOIN Comments AS C ON P.Id = C.PostId LEFT JOIN Votes AS PV ON P.Id = PV.PostId AND PV.VoteTypeId = 2 GROUP BY P.Id, P.OwnerUserId), RecentCloseHistory AS (SELECT PH.PostId, HT.Name AS HistoryType, PH.CreationDate FROM PostHistory AS PH JOIN PostHistoryTypes AS HT ON PH.PostHistoryTypeId = HT.Id WHERE HT.Name IN ('Post Closed', 'Post Reopened') AND PH.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserBadgeStats AS (SELECT UserId, COUNT(CASE WHEN Class = 1 THEN 1 END) AS GoldBadges, COUNT(CASE WHEN Class = 2 THEN 1 END) AS SilverBadges, COUNT(CASE WHEN Class = 3 THEN 1 END) AS BronzeBadges FROM Badges GROUP BY UserId) SELECT U.DisplayName, U.Reputation, UR.Rank, PS.PostId, PS.CommentCount, PS.VoteCount, PS.AverageScore, COALESCE(RCH.RecentActivity, 'No Recent Activity') AS RecentActivity, UBS.GoldBadges, UBS.SilverBadges, UBS.BronzeBadges FROM Users AS U JOIN UserReputation AS UR ON U.Id = UR.Id LEFT JOIN PostStats AS PS ON U.Id = PS.OwnerUserId LEFT JOIN (SELECT PostId, GROUP_CONCAT(HistoryType, ', ') AS RecentActivity FROM RecentCloseHistory GROUP BY PostId) AS RCH ON PS.PostId = RCH.PostId LEFT JOIN UserBadgeStats AS UBS ON U.Id = UBS.UserId WHERE U.Reputation > 1000 AND (NOT (U.Location IS NULL) OR NOT (U.WebsiteUrl IS NULL)) ORDER BY U.Reputation DESC NULLS FIRST, PS.AverageScore DESC NULLS FIRST LIMIT 100